// Extract context from the request
const request = $input.first().json;
const now = new Date();
const hour = now.getHours();
const dayOfWeek = now.getDay();
const isWeekend = dayOfWeek === 0 || dayOfWeek === 6;

// Determine time context
let timeContext = 'day';
if (hour < 6) timeContext = 'night';
else if (hour < 12) timeContext = 'morning';
else if (hour < 18) timeContext = 'afternoon';
else if (hour < 22) timeContext = 'evening';
else timeContext = 'night';

// Create context object
const context = {
  timestamp: now.toISOString(),
  time_context: timeContext,
  hour: hour,
  is_weekend: isWeekend,
  user_request: request.request || 'general assistance',
  location: request.location || 'home',
  urgency: request.urgency || 'normal',
  weather_condition: request.weather || 'unknown'
};

return [{ json: context }];

