// Parse AI response and prepare actions
let aiResponse;
try {
  const responseText = $input.first().json.choices[0].message.content;
  aiResponse = JSON.parse(responseText);
} catch (error) {
  return [{
    json: {
      error: 'AI response parsing failed',
      raw_response: $input.first().json.choices[0].message.content
    }
  }];
}

// Validate and structure actions
const actions = aiResponse.actions || [];
const validActions = actions.filter(action => 
  action.device && action.action && ['turn_on', 'turn_off', 'set_brightness', 'set_temperature'].includes(action.action)
);

// Group actions by priority
const highPriority = validActions.filter(a => a.priority === 'high');
const mediumPriority = validActions.filter(a => a.priority === 'medium');
const lowPriority = validActions.filter(a => a.priority === 'low');

return [{
  json: {
    actions: validActions,
    priority_groups: {
      high: highPriority,
      medium: mediumPriority,
      low: lowPriority
    },
    ai_message: aiResponse.ai_message || 'Smart home actions executed',
    total_actions: validActions.length,
    energy_impact: aiResponse.estimated_energy_impact || 'unknown'
  }
}];

// Process actions by type and execute them
const actions = $input.first().json.actions;
const results = [];

for (const action of actions) {
  try {
    let serviceData = { entity_id: action.device };

    // Add specific parameters based on action type
    if (action.brightness) serviceData.brightness_pct = action.brightness;
    if (action.temperature) serviceData.temperature = action.temperature;
    if (action.color_temp) serviceData.color_temp = action.color_temp;

    // Determine the service to call
    let service = action.action;
    let domain = action.device.split('.')[0];

    // Map actions to services
    if (action.action === 'set_brightness') service = 'turn_on';
    if (action.action === 'set_temperature' && domain === 'climate') service = 'set_temperature';

    results.push({
      device: action.device,
      action: action.action,
      service_data: serviceData,
      domain: domain,
      service: service,
      reason: action.reason,
      status: 'pending'
    });
  } catch (error) {
    results.push({
      device: action.device,
      action: action.action,
      error: error.message,
      status: 'failed'
    });
  }
}

return [{ json: { actions: results, total: results.length } }];

